// Persian (Farsi) copy for the app.
//
// The screens were written in English. Rather than scatter hundreds of
// ternaries through the JSX, the strings are listed here against their English
// and looked up at render time: tx('fa', 'Days owed'). A string that has no
// entry yet reads exactly as it does in English, so an untranslated label is
// never a blank.
//
// Persian is written right-to-left, so `isRtl('fa')` is true and the app sets
// the layout direction. Numbers stay in the Latin digits Iranians actually
// read: the app's own arabicNumeral pass is applied to Arabic only, never to
// Persian, for exactly that reason.
//
// Accessibility labels stay in English on purpose — the QA scripts drive the
// screens by them, in every language.

