  'Android is not allowing this app to set exact alarms, so the adhan cannot be timed to the prayer. Your notification tone will sound instead. Allow alarms and it will play properly.': 'اندروید به این برنامه اجازه نمی‌دهد هشدارهای دقیق تنظیم کند، بنابراین اذان نمی‌تواند دقیقاً با وقت نماز هماهنگ شود. در عوض زنگ اعلان شما به صدا درمی‌آید. اجازهٔ هشدارها را بدهید تا درست پخش شود.',
  'Android sometimes delays alarms for apps it thinks are idle, which can make the adhan arrive late. Exempting this app takes one tap.': 'اندروید گاه هشدارهای برنامه‌هایی را که بیکار می‌پندارد به تأخیر می‌اندازد، که ممکن است اذان را دیر برساند. مستثنا کردن این برنامه یک لمس است.',
  'Android will not delay this app’s reminders while it is saving power.': 'اندروید هنگام صرفه‌جویی در باتری، یادآوری‌های این برنامه را به تأخیر نمی‌اندازد.',
  'Another sets no minimum at all, and counts any bleeding as hayd once it has begun.': 'دیدگاهی دیگر هیچ حداقلی نمی‌گذارد و هر خونریزی‌ای را، همین که آغاز شد، حیض می‌شمارد.',
