  'Bathe and dress in the Ihram garments, then make the intention for the rites you have chosen and begin the Talbiyah. The prohibitions of Ihram now apply until you have stoned, sacrificed and shaved or trimmed.': 'غسل کنید و جامه‌های احرام بپوشید، سپس برای مناسکی که برگزیده‌اید نیت کنید و تلبیه را آغاز کنید. از این لحظه ممنوعیت‌های احرام برقرار است تا آنکه رمی کنید، قربانی کنید و بتراشید یا کوتاه کنید.',
