  'Bismillah': 'بسم‌الله',
  'Bleeding after childbirth is commonly counted up to 40 days.': 'خونریزیِ پس از زایمان معمولاً تا 40 روز شمرده می‌شود.',
  'Bleeding after childbirth is commonly counted up to {n} days.': 'خون‌ریزی پس از زایمان معمولاً تا {n} روز محاسبه می‌شود.',
  'Bleeding after childbirth is counted as nifas while it lasts, up to the outer limit. Its rules follow those of hayd for the days it runs.': 'خونریزیِ پس از زایمان، تا زمانی که ادامه دارد و تا حدِ بیشینه، نِفاس شمرده می‌شود. احکامِ آن در روزهایی که ادامه می‌یابد، تابعِ احکامِ حیض است.',
  'Bleeding days': 'روزهای خون‌ریزی',
  'Bleeding is not always hayd, and the difference decides whether the prayer and the fast are due. Answer the two questions below and the app will hold them against your own pattern and against the limits commonly cited.': 'خون‌ریزی همیشه حیض نیست، و همین تفاوت تعیین می‌کند که نماز و روزه بر عهده باشد یا نه. به دو پرسشِ پایین پاسخ دهید و برنامه آن‌ها را با الگوی خودِ شما و با حدودی که معمولاً گفته می‌شود می‌سنجد.',
  'Bleeding outside the pattern of hayd or nifas: ongoing spotting, a wound, or bleeding that runs past the limits above. It does not prevent the prayer or the fast. The well-known guidance is to wash, protect the area, and make wudu for the time of each prayer rather than once for the day.': 'خونریزیِ بیرون از الگوی حیض یا نفاس: لکه‌بینیِ مداوم، زخم، یا خونریزی‌ای که از حدهای یادشده می‌گذرد. این مانعِ نماز و روزه نیست. راهنماییِ شناخته‌شده این است که بشویید، موضع را بپوشانید، و برای وقتِ هر نماز وضو بگیرید، نه یک بار برای کلِ روز.',
  'Bleeding that begins inside that gap is not counted as a new period.': 'خونریزی‌ای که در میانِ آن فاصله آغاز شود، دوره‌ای تازه شمرده نمی‌شود.',
  'Bleeding that continues past the outer limit is treated as istihada from that point.': 'خونریزی‌ای که از حدِ بیشینه فراتر می‌رود، از همان نقطه اِستِحاضه به‌شمار می‌آید.',
  'Bleeding that is not a period': 'خونی که عادت ماهانه نیست',
