  'Complete Surah recitations from published reciters, used when you play a whole Surah rather than verse by verse.': 'تلاوت‌های کامل سوره از قاریان منتشرشده، که هنگام پخش یک سورهٔ کامل به کار می‌رود نه آیه‌به‌آیه.',
