  'Complete dryness: nothing at all is seen when checking, so the place remains clean and dry. For many women this is the clearer of the two signs, and it is reached a day or two after the discharge stops.': 'خشکیِ کامل: هنگام بررسی هیچ چیزی دیده نمی‌شود، پس موضع پاک و خشک می‌ماند. برای بسیاری از زنان این نشانه از آنِ دیگر روشن‌تر است، و یک یا دو روز پس از قطعِ ترشح به دست می‌آید.',
