  'Days': 'روزها',
  'Days fasted in each month, oldest first.': 'روزهای روزه در هر ماه، از قدیمی‌تر به جدیدتر.',
  'Days missed through hayd or nifas are made up one for one. There is no fidyah on them, because fidyah belongs to the one who cannot make the day up at all. A woman who can fast later fasts later.': 'روزهایی که بر اثرِ حیض یا نفاس از دست می‌رود، یک‌به‌یک قضا می‌شود. فَیدیه‌ای بر آن‌ها نیست، زیرا فدیه از آنِ کسی است که اصلاً نمی‌تواند آن روز را قضا کند. زنی که می‌تواند بعداً روزه بگیرد، بعداً روزه می‌گیرد.',
  'Days of Ramadan missed through menstruation or post-natal bleeding are made up before the next Ramadan, one day for each day. They do not need to be consecutive, and they may be spread through the year — but they are a debt, so most women keep a running count. This area records those days for you and keeps the scorecard honest as you settle them.': 'روزهای رمضان که بر اثرِ حیض یا خونریزیِ پس از زایمان از دست می‌رود، پیش از رمضانِ بعد قضا می‌شود، برای هر روز یک روز. لازم نیست پیاپی باشند و می‌توان آن‌ها را در طولِ سال پخش کرد — اما آن‌ها دِین هستند، از این رو بیشترِ زنان شمارشِ جاری نگه می‌دارند. این بخش آن روزها را برای شما ثبت می‌کند و هنگامی که آن‌ها را ادا می‌کنید، حساب را درست نگه می‌دارد.',
  'Days owed': 'روزهای بدهی',
  'Debts and bills due': 'بدهی‌ها و قبوض سررسیدشده',
  'Declined earlier. Turn it on in the system settings for this app.': 'پیش‌تر رد شده. آن را در تنظیمات سیستم این برنامه روشن کنید.',
