  'Deletion': 'حذف',
  'Deodorant without perfume; a crystal or alum stick is the safe bet': 'دئودورانت بدون بو؛ استیک کریستال یا زاج انتخاب مطمئنی است',
  'Details differ between legal schools; follow the imam and seek local scholarly guidance.': 'جزئیات میانِ مذاهب تفاوت دارد؛ از امام پیروی کنید و راهنماییِ علمیِ محلی بخواهید.',
  'Deutsch': 'Deutsch',
  'Dhikr': 'ذکر',
  'Dhikr counter': 'شمارنده ذکر',
  'Dhikr, dua, charity, kindness to family, listening to the Quran, and seeking knowledge all continue. Nothing about these days closes the door to a person’s relationship with Allah — they are part of the worship of a woman’s life, not a suspension of it. Many find the regular adhkar of morning and evening especially valuable here, since the habit continues even when the prayer does not.': 'ذکر، دعا، صدقه، نیکی به خانواده، گوش دادن به قرآن و طلبِ علم، همه ادامه می‌یابند. هیچ چیز در این روزها درِ رابطهٔ انسان با خدا را نمی‌بندد — این‌ها بخشی از عبادتِ زندگیِ یک زن هستند، نه تعلیقِ آن. بسیاری در اینجا اذکارِ همیشگیِ صبح و شام را به‌ویژه ارزشمند می‌یابند، زیرا این عادت ادامه می‌یابد حتی آنگاه که نماز نمی‌ماند.',
  'Dhikr, tasbih and istighfar': 'ذکر، تسبیح و استغفار',
