  'Downloads': 'بارگیری‌ها',
  'Downloads the Arabic script and translation you have selected, one Surah at a time. Preparation continues while you use other screens and prioritizes your current reading Surah.': 'خط عربی و ترجمه‌ای را که برگزیده‌اید، یک سوره در میان، بارگیری می‌کند. آماده‌سازی در حالی که صفحه‌های دیگر را به کار می‌برید ادامه می‌یابد و سوره‌ای را که اکنون می‌خوانید در اولویت می‌گذارد.',
  'Drawn at random from what you are working on.': 'به‌طور تصادفی از آنچه روی آن کار می‌کنید برگرفته شده.',
  'Dua': 'دعا',
  'Dua and remembrance': 'دعا و ذکر',
  'Dua is worship, and it is never closed. The days in which the prayer is lifted from a woman are, by many accounts, days in which her asking is especially her own — nothing stands between her and it.': 'دعا عبادت است و هرگز بسته نمی‌شود. روزهایی که نماز از زن برداشته می‌شود، به گفتهٔ بسیاری، روزهایی است که درخواستِ او در آن‌ها به‌ویژه از آنِ خودِ اوست — هیچ چیز میانِ او و آن نمی‌ایستد.',
  'Duas': 'دعاها',
  'Duas and Adhkar': 'دعاها و اذکار',
  'Duas and remembrance': 'دعاها و اذکار',
  'Dubai, United Arab Emirates': 'دبی، امارات متحدهٔ عربی',
  'Duha': 'ضحی',
  'ENTRIES': 'ورودی‌ها',
  'Each Hizb contains four quarter-Hizb sections.': 'هر حزب شامل چهار بخش ربع حزب است.',
  'Each Tajweed rule is coloured where it applies. Colours are a learning aid and do not replace study with a qualified teacher.': 'هر قاعدهٔ تجوید در جای کاربردش رنگی می‌شود. رنگ‌ها کمک آموزشی‌اند و جایگزین آموختن نزد استاد واجد شرایط نیستند.',
  'Each collection carries Arabic and English editions, so every hadith can be read in both. Collections are read on demand: opening one costs a single request for its list of books.': 'هر مجموعه نسخه‌های عربی و انگلیسی دارد، از این رو هر حدیث را می‌توان به هر دو زبان خواند. مجموعه‌ها به درخواست خوانده می‌شوند: باز کردنِ یکی، تنها یک درخواست برای فهرست کتاب‌هایش هزینه دارد.',
  'Each collection carries Arabic and English editions, so every hadith you read is shown in both. Nothing is paraphrased.': 'هر مجموعه نسخه‌های عربی و انگلیسی دارد، از این رو هر حدیثی که می‌خوانید در هر دو نشان داده می‌شود. هیچ چیز بازگویی نمی‌شود.',
  'Each morning': 'هر صبح',
  'Each press uncovers a few more words, so you are never completely stuck.': 'هر بار فشردن، واژگان بیشتری را آشکار می‌کند، پس هرگز کاملاً درنمی‌مانید.',
  'Each square is one day, oldest first. The fuller the square, the more of the five you marked.': 'هر مربع یک روز است، از قدیمی‌تر به جدیدتر. هرچه مربع پُرتر باشد، شمار بیشتری از پنج نماز را ثبت کرده‌اید.',
  'Earlier births': 'تولدهای پیشین',
  'Earlier end': 'پایان زودتر',
  'Earlier start': 'شروع زودتر',
  'Earth or land': 'زمین یا سرزمین',
  'Edit': 'ویرایش',
  'Edit the entry': 'ویرایش ورودی',
  'Edit your note': 'ویرایش یادداشت',
  'Egyptian Authority': 'هیئت مصری',
