  'FOR DHUHR, ASR, MAGHRIB AND ISHA': 'برای ظهر، عصر، مغرب و عشا',
  'FOR FAJR ONLY': 'فقط برای نماز صبح',
  'Face ID': 'Face ID',
  'Face and fingerprint unlock are ready on this device': 'بازگشایی با چهره و اثر انگشت روی این دستگاه آماده است',
  'Face masks, spare glasses or lenses, eye drops': 'ماسک صورت، عینک یا لنز اضافه، قطرهٔ چشم',
  'Face the Kaaba from where you stand': 'از هر جا ایستاده‌اید رو به کعبه کنید',
  'Face the Qibla with intention.': 'با نیت رو به قبله کنید.',
  'Failed': 'ناموفق',
  'Faith': 'ایمان',
  'Fajr': 'صبح',
  'Fajr adhan': 'اذان صبح',
  'Fajr has its own call, chosen separately. All recordings are stored in the app.': 'فجر اذان ویژهٔ خود را دارد که جداگانه برگزیده می‌شود. همهٔ ضبط‌ها در برنامه ذخیره شده‌اند.',
  'Fajr has its own call, so it is chosen on its own. Every other prayer shares the second choice. All recordings are stored in the app and play with no connection.': 'فجر اذان ویژهٔ خود را دارد، از این رو جداگانه برگزیده می‌شود. هر نمازِ دیگر در گزینهٔ دوم شریک است. همهٔ ضبط‌ها در برنامه ذخیره شده‌اند و بی‌نیاز از اتصال پخش می‌شوند.',
  'Fajr only': 'تنها فجر',
  'Fast days missed through menstruation or the post-natal days are made up one for one, before the next Ramadan. This is the running count.': 'روزهای روزه‌ای که بر اثر عادت ماهانه یا روزهای پس از زایمان از دست رفته‌اند، پیش از رمضان بعدی یکی‌به‌یکی قضا می‌شوند. این شمارشِ جاری است.',
  'Fast days that fall in hayd or nifas are owed, and are kept here.': 'روزهای روزه که در حیض یا نفاس افتاده‌اند قضا دارند و اینجا نگه داشته می‌شوند.',
  'Fast days that fall in them are not fasted, and are owed — the Qada screen will keep the count.': 'روزهای روزه‌ای که در آن‌ها می‌افتد، روزه گرفته نمی‌شود و قضا دارد — صفحهٔ قضا شمارش را نگه می‌دارد.',
  'Faster': 'سریع‌تر',
  'Fasting': 'روزه',
  'Fasting is due, and a fast kept in them counts — it is not owed again.': 'روزه واجب است، و روزه‌ای که در آن‌ها گرفته شود به حساب می‌آید — دوباره قضا ندارد.',
  'Fasting record': 'سابقه روزه',
  'Fasting timetable': 'جدول روزه',
  'Fasting, and the days owed': 'روزه، و روزه‌های قضا',
  'Featured reading': 'خواندنِ برگزیده',
  'Feet': 'پاها',
  'Fetched in 4 MB pieces, checked against the size the source reports, then saved.': 'در قطعات 4 مگابایتی دریافت می‌شود، با اندازه‌ای که منبع گزارش می‌دهد سنجیده می‌شود، سپس ذخیره می‌گردد.',
  'Fetching…': 'در حال دریافت…',
  'Fewer': 'کمتر',
  'Files are written to a temporary partial file first, checked against the size the server reported, and only then moved into place. A failed download is deleted rather than left half-written.': 'پرونده‌ها نخست به یک پروندهٔ موقت و ناتمام نوشته می‌شوند، با اندازه‌ای که کارساز گزارش داده سنجیده می‌شوند، و تنها پس از آن به جای خود منتقل می‌گردند. بارگیریِ ناموفق حذف می‌شود، نه آنکه نیمه‌نوشته رها گردد.',
  'Find the direction of the Kaaba': 'جهتِ کعبه را بیابید',
  'Finding steadiness of heart through remembrance of Allah.': 'یافتنِ آرامشِ دل از راهِ یادِ خدا.',
  'Fingerprint': 'اثر انگشت',
  'Finish this reading': 'پایان این خواندن',
  'Fix now': 'رفع مشکل',
  'Flag a verse during practice and it will wait for you here.': 'هنگام تمرین آیه‌ای را علامت بزنید و اینجا منتظر شما می‌ماند.',
  'Flagged': 'علامت‌گذاری‌شده',
  'Flow': 'جریان',
  'Focus mode': 'حالت تمرکز',
  'Follow the imam for the two-rakah prayer and additional takbirs.': 'در نمازِ دو رکعتی و تکبیرهای افزون از امام پیروی کنید.',
  'Font size': 'اندازه قلم',
  'Food and drink': 'خوراک و نوشیدنی',
  'For Eid al-Fitr, eat before leaving; for Eid al-Adha, local practice may differ.': 'در عیدِ فطر پیش از بیرون رفتن چیزی بخورید؛ در عیدِ اضحی روشِ محلی ممکن است تفاوت کند.',
  'For formally entering Islam, connect with a trusted local mosque for support and learning.': 'برای ورودِ رسمی به اسلام، برای پشتیبانی و آموزش با یک مسجدِ محلیِ موردِ اعتماد در پیوند باشید.',
  'For what you do in these specific days, ask a scholar you trust.': 'برای آنچه در این روزهای معیّن انجام می‌دهید، از عالمی که به او اعتماد دارید بپرسید.',
  'For women': 'برای زنان',
  'For your day': 'برای روز شما',
  'Forgiveness': 'آمرزش',
  'Form the intention and face the Qibla.': 'نیت کنید و رو به قبله بایستید.',
  'Forty': 'چهل',
  'Found online — saved on this device for next time.': 'به‌صورت برخط یافت شد — برای دفعهٔ بعد روی این دستگاه ذخیره شد.',
  'Four digits. There is no reset link and no recovery email — this code lives on this device only, so choose one you will remember.': 'چهار رقم. نه پیوندی برای بازنشانی هست و نه رایانامه‌ای برای بازیابی — این رمز تنها روی همین دستگاه است، پس رمزی برگزینید که به خاطر بسپارید.',
  'Four shortcuts, and which four is yours to say. Pick one to change it.': 'چهار میان‌بر، و اینکه کدام چهار تا، با شماست. یکی را برگزینید تا تغییرش دهید.',
  'Français': 'Français',
  'Free space': 'فضای آزاد',
  'Free space: ': 'فضای آزاد: ',
  'French': 'فرانسوی',
