  'GOD [Himself] proffers evidence - and [so do] the angels and all who are endowed with knowledge - that there is no deity save Him, the Upholder of Equity: there is no deity save Him, the Almighty, the Truly Wise.': 'خداوند گواهی می‌دهد که هیچ معبودی جز او نیست، و فرشتگان و دارندگانِ دانش نیز گواهی می‌دهند، در حالی که به عدالت برپاست: هیچ معبودی جز او نیست، که توانای شکست‌ناپذیر و حکیم است.',
  'GOLD NISAB': 'نصاب طلا',
  'GROSS ASSETS': 'دارایی‌های ناخالص',
  'GUIDES': 'راهنماها',
  'General': 'عمومی',
  'General Authority for the care of the Two Holy Mosques': 'ادارهٔ کل امور دو مسجد مقدس',
  'Gentle, local reminders': 'یادآوری‌های ملایم و محلی',
  'Get started': 'شروع کنید',
  'Get the recordings': 'دریافت فایل‌های صوتی',
  'Ghusl': 'غسل',
  'Ghusl is for the prayer, not the fast': 'غسل برای نماز است، نه برای روزه',
  'Ghusl is not required by the bleeding itself; it is for the hayd that preceded it.': 'غسل را خودِ خونریزی واجب نمی‌کند؛ غسل برای حیضی است که پیش از آن بوده است.',
  'Ghusl once, now — the days that follow are days of prayer, not days off.': 'یک غسل، هم‌اکنون — روزهای پس از آن روزهای نماز هستند، نه روزهای تعطیل.',
  'Ghusl once, now — the major impurity of the hayd is lifted by it, and the bleeding that continues does not bring it back.': 'یک غسل، هم‌اکنون — نجاستِ بزرگِ حیض با آن برطرف می‌شود، و خونریزی‌ای که ادامه می‌یابد آن را بازنمی‌گرداند.',
  'Girl': 'دختر',
  'Girls': 'دختران',
  'Give charity and reconcile with others.': 'صدقه بدهید و با دیگران آشتی کنید.',
  'Give early enough to reach them before Eid prayer.': 'به‌قدری زود بدهید که پیش از نمازِ عید به دستشان برسد.',
  'Given': 'داده‌شده',
  'Given to either': 'داده‌شده به هر یک',
