  'If bleeding continues past what is usual for you, the commonly cited limits are fifteen days for hayd and forty for nifas. Beyond them, the bleeding is generally treated as istihadha: pray, fast, and speak to a scholar and a doctor. Neither of them will find the question unusual.': 'اگر خونریزی از مقدارِ همیشگیِ شما فراتر رود، حدهایی که معمولاً گفته می‌شود پانزده روز برای حیض و چهل روز برای نفاس است. فراتر از آن‌ها، خونریزی به‌طورِ کلّی استحاضه به‌شمار می‌آید: نماز بگزارید، روزه بگیرید، و با یک عالم و یک پزشک سخن بگویید. هیچ‌یک از آن دو این پرسش را نامعمول نخواهد یافت.',
  'If bleeding stops before Fajr and the fast is intended that night, the fast stands. Ghusl is required before the prayer; it is not a condition of the fast itself. A woman may wake in a state that defers Fajr and still hold a valid fast.': 'اگر خونریزی پیش از فجر قطع شود و نیتِ روزه در آن شب صورت گیرد، روزه درست است. غسل پیش از نماز واجب است؛ شرطِ خودِ روزه نیست. چه‌بسا زنی در حالتی بیدار شود که نمازِ فجر را به تأخیر می‌اندازد و در عین حال روزه‌ای درست داشته باشد.',
  'If this changes, this page changes with it.': 'اگر این تغییر کند، این صفحه با آن تغییر می‌کند.',
