  'Leave ‘Arafah after sunset — before dawn — and go to Muzdalifah, where you pray Maghrib and ‘Isha together and spend the night. Gather the pebbles for the stoning here, then leave for Mina before or around dawn.': 'پس از غروب — پیش از سپیده — عرفات را ترک کنید و به مُزدَلِفه بروید، جایی که نمازِ مغرب و عشا را با هم می‌خوانید و شب را می‌گذرانید. سنگریزه‌های رمی را در اینجا گرد آورید، سپس پیش از سپیده یا در حدودِ آن به سوی مِنیٰ بروید.',
  'Left out: downloaded recitation audio, which lives as files on this device and can be downloaded again, and the backup password itself.': 'کنار گذاشته شده: صدای بارگیری‌شدهٔ تلاوت، که به صورت پرونده روی این دستگاه است و دوباره قابل بارگیری است، و خودِ رمز پشتیبان.',
