  'Narrated Anas bin Malik:The Prophet (ﷺ) said, "Take Suhur as there is a blessing in it': 'به روایتِ انس بن مالک: پیامبر ﷺ فرمود: «سَحَر را بخورید، که در آن برکت است',
  'Narrated Talha bin `Abdullah bin `Auf:I offered the funeral prayer behind Ibn `Abbas and he recited Al-Fatiha and said, "You should know that it (i.e. recitation of Al-Fatiha) is the tradition of the Prophet Muhammad (ﷺ)': 'به روایتِ طلحه بن عبدالله بن عوف: پشتِ سرِ ابن‌عباس نمازِ جنازه گزاردم و او سورهٔ حمد را خواند و گفت: «بدانید که این — یعنی خواندنِ سورهٔ حمد — سنّتِ پیامبر خدا محمّد ﷺ است',
  'Narrator': 'راوی',
  'Naskh': 'نسخ',
  'Natural bleeding that comes to a woman at its known time, without a cause such as injury or illness. Commonly cited limits are a minimum of three days and a maximum of fifteen, with at least fifteen days of purity between two cycles. Anything outside that pattern is usually treated as istihadha, and the details belong with a scholar.': 'خونریزیِ طبیعی‌ای که در وقتِ شناخته‌شدهٔ خود به زن می‌رسد، بی‌آنکه علّتی چون زخم یا بیماری در میان باشد. حدهایی که معمولاً گفته می‌شود کمینه سه روز و بیشینه پانزده روز است، با دست‌کم پانزده روز پاکی میانِ دو چرخه. هر چه بیرون از این الگو باشد معمولاً استحاضه به‌شمار می‌آید، و جزئیاتِ آن نزدِ یک عالم است.',
