  'Open settings': 'باز کردن تنظیمات',
  'Open system settings': 'گشودنِ تنظیماتِ سیستم',
  'Open the Android battery settings': 'گشودن تنظیمات باتری اندروید',
  'Open the Mushaf': 'گشودنِ مصحف',
  'Open the audio player': 'گشودن پخش‌کنندهٔ صوت',
  'Open the full reflection': 'گشودن تأمل کامل',
  'Open the prophets catalogue': 'گشودن فهرست پیامبران',
  'Open this page by choosing an item from the list before it.': 'این صفحه را با انتخاب موردی از فهرست پیش از آن بگشایید.',
  'Open to you': 'برای شما باز است',
  'Open to you without question — no school disputes it. Put a reciter on and let the day be filled with the sound of it. Listening is not a lesser substitute for reciting; it is its own worship, and these are often the days a woman listens most.': 'بی‌هیچ پرسشی بر شما گشوده است — هیچ مذهبی در آن اختلاف ندارد. یک قاری را بگذارید و بگذارید روز از صدای آن پُر شود. گوش دادن جانشینِ فرودست‌تری برای تلاوت نیست؛ خود عبادتی است، و این‌ها غالباً روزهایی است که یک زن بیش از همه گوش می‌دهد.',
  'Open verse actions to add a reflection.': 'برای افزودن تأمل، عملیات آیه را بگشایید.',
  'Opening…': 'در حال باز کردن…',
  'Opens a screen': 'یک صفحه باز می‌کند',
  'Optional': 'اختیاری',
  'Optional — anything that helps us find it.': 'اختیاری — هر چیزی که در یافتن آن کمک کند.',
  'Optional. Nothing is downloaded until you finish setting up.': 'اختیاری. تا پایان راه‌اندازی چیزی بارگیری نمی‌شود.',
  'Or an unscented anti-chafe balm in a stick': 'یا بالم ضدسایش بدون بو به صورت استیکی',
  'Or enter coordinates': 'یا وارد کردن مختصات',
  'Or paste one instead': 'یا به جای آن یکی را بچسبانید',
