  'Palestine': 'فلسطین',
  'Parents and family': 'پدر و مادر و خانواده',
  'Part of the verse is blanked, the rest guides you.': 'بخشی از آیه پوشانده شده و بقیه شما را راهنمایی می‌کند.',
  'Partly translated': 'تا حدی ترجمه شده',
  'Partly translated — some screens stay in English': 'تا حدی ترجمه شده — برخی صفحه‌ها به انگلیسی می‌مانند',
  'Passages inviting reflection on creation, order and purpose.': 'آیاتی که به تأمّل در آفرینش، نظم و غایت فرا می‌خوانند.',
  'Passport with at least six months left on it': 'گذردرنامه‌ای که دست‌کم شش ماه از اعتبارش باقی مانده باشد',
  'Password': 'رمز عبور',
  'Password changed. Backups already made still open with the old one.': 'رمز تغییر کرد. پشتیبان‌هایی که پیش‌تر ساخته شده‌اند همچنان با رمز قبلی باز می‌شوند.',
  'Password removed. Backups already made still open with it.': 'رمز حذف شد. پشتیبان‌هایی که پیش‌تر ساخته شده‌اند همچنان با آن باز می‌شوند.',
  'Password set. Nothing can recover it — not this app, and not anyone else.': 'رمز تنظیم شد. هیچ چیز نمی‌تواند آن را بازیابی کند — نه این برنامه و نه هیچ کس دیگر.',
  'Past forty days — speak to a scholar and a doctor': 'بیش از چهل روز — با یک عالم و یک پزشک مشورت کنید',
  'Past that limit the extra days are treated as istihada rather than as nifas.': 'فراتر از آن حد، روزهای افزون استحاضه به‌شمار می‌آیند، نه نفاس.',
