  'Permission': 'مجوز',
  'Permission and scheduling happen on your device. No notification profile is sent to us.': 'اجازه و زمان‌بندی روی دستگاه شما انجام می‌شود. هیچ نمایهٔ اعلانی برای ما فرستاده نمی‌شود.',
  'Permission was declined earlier, so reminders stay off. You can turn them on in the system settings for this app at any time.': 'پیش‌تر اجازه رد شده است، از این رو یادآوری‌ها خاموش می‌مانند. هر زمان بخواهید می‌توانید آن‌ها را در تنظیمات سیستمِ این برنامه روشن کنید.',
