  'Pour water over the head three times, so it reaches the roots of the hair.': 'سه بار بر سر آب بریزید، به گونه‌ای که به ریشهٔ موها برسد.',
  'Pour water over the whole body, right side first, making sure no patch of skin is left dry.': 'بر تمام بدن آب بریزید، نخست سمت راست، و مطمئن شوید هیچ بخشی از پوست خشک نماند.',
