  'Practised': 'تمرین‌شده',
  'Praise, fills the scale': 'ستایش، که ترازو را پُر می‌کند',
  'Pray after Isha, individually or with the congregation.': 'پس از عشا نماز بگزارید، به‌تنهایی یا با جماعت.',
  'Pray in sets of two rakahs.': 'در دسته‌های دو رکعتی نماز بگزارید.',
  'Pray two non-obligatory rakahs.': 'دو رکعت نمازِ مستحب بگزارید.',
  'Pray two rak‘ahs and give thanks': 'دو رکعت نماز بخوانید و سپاس بگزارید',
  'Pray where you can in the Haram, give charity if you are able, and keep the supplication that is offered after a completed rite. Many then repeat the Umrah from Al-Tan‘īm or perform it again for someone else — that is a matter of your own intention and capacity.': 'در حرم هر جا که می‌توانید نماز بگزارید، اگر در توان دارید صدقه بدهید، و دعایی را که پس از یک منسکِ کامل‌شده خوانده می‌شود نگه دارید. بسیاری سپس عمره را از تنعیم تکرار می‌کنند یا آن را از سویِ دیگری به جای می‌آورند — این بر پایهٔ نیت و توانِ خودِ شماست.',
  'Prayer': 'نماز',
  'Prayer Reminders': 'یادآورهای نماز',
  'Prayer and fasting are due': 'نماز و روزه واجب است',
  'Prayer and fasting are not due in these days': 'در این روزها نماز و روزه واجب نیست',
  'Prayer and fasting are not due while it continues, and the fasts are owed.': 'تا زمانی که ادامه دارد نماز و روزه بر عهده نیست، و آن روزه‌ها قضا دارند.',
  'Prayer and fasting resume from here': 'نماز و روزه از اینجا از سر گرفته می‌شود',
  'Prayer and fasting resume from here, and a fast kept after the ghusl counts.': 'از اینجا نماز و روزه از سر گرفته می‌شود، و روزه‌ای که پس از غسل گرفته شود به حساب می‌آید.',
  'Prayer and fasting resume from here, and the fasts of these days count.': 'از اینجا نماز و روزه از سر گرفته می‌شود، و روزه‌های این روزها به حساب می‌آید.',
  'Prayer during the monthly cycle': 'نماز در چرخهٔ ماهانه',
  'Prayer is due in these days, and the prayer of each one is prayed.': 'در این روزها نماز بر عهده است، و نمازِ هر یک از آن‌ها خوانده می‌شود.',
  'Prayer record, reading position, bookmarks, notes, settings, chosen city and language. Removed by clearing storage or uninstalling.': 'سابقهٔ نماز، جایگاه خواندن، نشانک‌ها، یادداشت‌ها، تنظیمات، شهر برگزیده و زبان. با پاک کردن حافظه یا حذف برنامه از بین می‌روند.',
  'Prayer reminders': 'یادآوری‌های نماز',
  'Prayer reminders are ready': 'یادآورهای نماز آماده است',
  'Prayer schedule': 'برنامهٔ نماز',
  'Prayer spaces around you': 'فضاهای نماز در اطرافِ شما',
  'Prayer times': 'اوقات نماز',
  'Prayer times, Qibla and fasting times read from one place. Tap to choose a city or enter coordinates.': 'اوقات نماز، قبله و زمان‌های روزه از یک جا خوانده می‌شوند. برای برگزیدن شهر یا وارد کردن مختصات بزنید.',
  'Prayer times, Qibla and the fasting timetable all read from one place. Search for your city, or use your location once. This is asked only here — you can change it any time in Settings.': 'اوقات نماز، قبله و جدول روزه، همه از یک جا خوانده می‌شوند. شهر خود را جست‌وجو کنید، یا یک بار از مکان خود استفاده کنید. این تنها همین‌جا پرسیده می‌شود — هر زمان بخواهید می‌توانید آن را در تنظیمات تغییر دهید.',
  'Prayer times, Qibla, Ramadan and nearby mosques all read from this one place. It is asked once and kept on this device.': 'اوقات نماز، قبله، رمضان و مسجدهای نزدیک، همه از همین یک جا خوانده می‌شوند. یک بار پرسیده می‌شود و روی این دستگاه نگه داشته می‌شود.',
  'Prayer times, the Hijri date, the Ramadan timetable, and the 604-page Mushaf layout with the Juz and Hizb divisions — kept with the app rather than asked for, so a page of the Quran opens without a connection. Every adhan recording is stored here too, eighteen for the day and two for dawn, which is what lets the call sound at Fajr with no network at all. The sun does not need the internet, and nothing about where you are is sent anywhere.': 'اوقات نماز، تاریخ هجری، جدول رمضان، و چیدمان مصحف 604 صفحه‌ای با تقسیمات جزء و حزب — همراهِ برنامه نگه داشته می‌شود نه اینکه درخواست شود، تا یک صفحه از قرآن بی‌نیاز از اتصال باز شود. هر ضبط اذان نیز در اینجا ذخیره شده است، هجده تا برای روز و دو تا برای سپیده، و این همان چیزی است که باعث می‌شود اذان در وقت فجر بدون هیچ شبکه‌ای به صدا درآید. خورشید به اینترنت نیاز ندارد، و هیچ چیز دربارهٔ جایی که هستید به جایی فرستاده نمی‌شود.',
