  'Quran TV and Sunnah TV play right here, from the broadcaster’s own stream. The other channels open outside this app, because carrying them here would need rights the app does not hold.': 'قرآن تی‌وی و سُنّه تی‌وی همین‌جا و از جریانِ خودِ پخش‌کننده پخش می‌شوند. شبکه‌های دیگر بیرون از این برنامه باز می‌شوند، زیرا آوردنشان به اینجا نیازمند حقوقی است که برنامه در اختیار ندارد.',
