  'Record the birth when it happens and the counter follows the days. Purity is marked the day the bleeding stops.': 'زایمان را هنگام وقوع ثبت کنید و شمارنده روزها را دنبال می‌کند. پاکی همان روزی که خون‌ریزی می‌ایستد علامت می‌خورد.',
