  'Record the days as they come. The averages and the prediction are worked out from your own history — nothing is assumed about what your cycle should look like.': 'روزها را همان‌گونه که پیش می‌آیند ثبت کنید. میانگین‌ها و پیش‌بینی از تاریخچهٔ خود شما به دست می‌آیند — هیچ فرضی دربارهٔ اینکه چرخه‌تان باید چگونه باشد وجود ندارد.',
