  'Sahih Muslim — the hadith of Umm Atiyya on the signs of purity': 'صحیح مسلم — حدیثِ امّ عطیّه دربارهٔ نشانه‌های پاکی',
  'Sahih al-Bukhari and Muslim — “Do what the pilgrim does, except do not circumambulate the House”': 'صحیح بخاری و مسلم — «هر چه حاجی انجام می‌دهد انجام بده، جز اینکه به گردِ خانه طواف نکنی»',
  'Sahih al-Bukhari, Kitab al-Hayd — the hadith of Aisha on making up fasts, not prayers': 'صحیح بخاری، کتابُ الحیض — حدیثِ عایشه دربارهٔ قضای روزه‌ها، نه نمازها',
  'Said for': 'گفته‌شده برای',
  'Salah Tracker': 'پیگیری نماز',
  'Salah counts the prayers you mark on the Prayer screen. Reading counts the verses you mark in the reader and the Mushaf pages you open. Dhikr comes from the Tasbih counter, and hifz from every verse you rate in recall practice. The week is kept on this device only.': 'شمارشِ نماز، نمازهایی را می‌شمارد که در صفحهٔ نماز علامت می‌زنید. شمارشِ خواندن، آیاتی را می‌شمارد که در خواننده علامت می‌زنید و صفحه‌های مصحفی را که می‌گشایید. ذکر از شمارندهٔ تسبیح می‌آید، و حفظ از هر آیه‌ای که در تمرینِ بازخوانی درجه‌بندی می‌کنید. این هفته تنها روی همین دستگاه نگه داشته می‌شود.',
  'Salah counts the prayers you mark on the Prayer screen. Reading counts the verses you mark in the reader and the Mushaf pages you open. Dhikr comes from the Tasbih counter, and hifz from every verse you rate in recall practice. Thirty days are kept, on this device only, and nothing is uploaded.': 'نماز، نمازهایی را می‌شمارد که در صفحهٔ نماز علامت می‌زنید. تلاوت، آیاتی را می‌شمارد که در خواننده علامت می‌زنید و صفحات مصحفی که باز می‌کنید. ذکر از شمارندهٔ تسبیح می‌آید، و حفظ از هر آیه‌ای که در تمرینِ بازخوانی درجه می‌دهید. سی روز نگه داشته می‌شود، تنها روی این دستگاه، و چیزی بارگذاری نمی‌شود.',
  'Salat al-Janazah is a communal obligation and is performed standing, without bowing or prostration.': 'نمازِ جنازه واجبی کفایی است و ایستاده گزارده می‌شود، بی‌رکوع و بی‌سجود.',
