  'Scholars differ on which of the two to measure against. The lower threshold brings more wealth into Zakat; take the choice to someone you trust.': 'علما در اینکه کدام یک از این دو ملاک سنجش باشد اختلاف دارند. آستانهٔ پایین‌تر دارایی بیشتری را مشمول زکات می‌کند؛ این انتخاب را نزد کسی که به او اعتماد دارید ببرید.',
  'Scholars differ. Reciting from memory is widely permitted; touching the physical mushaf is not, since it requires purification. On screens and phones the question turns on whether a device counts as a mushaf — many contemporary scholars permit reading and reciting from a phone for that reason, while others advise limiting it to looking and listening. Follow the position of a scholar you trust, and keep the Quran close either way: listening to recitation is open to everyone, in every state.': 'علما اختلاف دارند. تلاوت از حفظ به‌طورِ گسترده مجاز دانسته شده است؛ لمسِ مصحفِ فیزیکی نه، زیرا نیازمندِ طهارت است. در صفحه‌ها و گوشی‌ها، پرسش بر سرِ این است که آیا یک دستگاه مصحف به‌شمار می‌آید — بسیاری از علماِ معاصر از همین رو خواندن و تلاوت از گوشی را مجاز می‌دانند، در حالی که برخی دیگر توصیه می‌کنند به نگاه کردن و گوش دادن بسنده شود. از موضعِ عالمی که به او اعتماد دارید پیروی کنید، و به هر روی قرآن را نزدیک نگه دارید: گوش دادن به تلاوت در هر حالی برای همه باز است.',
