  'Towelling weave rather than thin cotton, which goes see-through when you sweat': 'بافت حوله‌ای به جای پنبهٔ نازک، که هنگام عرق کردن بدن‌نما می‌شود',
  'Track your prayers': 'نمازهایتان را پیگیری کنید',
  'Tracker': 'پیگیری',
  'Trackers and calculators': 'پیگیرها و ماشین‌حساب‌ها',
  'Translation': 'ترجمه',
  'Translation Compare': 'مقایسهٔ ترجمه‌ها',
  'Translation and tafsir are not the Quran in the sense that recitation is — they are the study of it, and study is not closed to you. Many women find these days become the most attentive reading of their month, precisely because the pace slows and the hurry goes out of it.': 'ترجمه و تفسیر، به آن معنا که تلاوت قرآن است، قرآن نیستند — آن‌ها مطالعهٔ قرآن هستند، و مطالعه بر شما بسته نیست. بسیاری از زنان درمی‌یابند که این روزها دقیق‌ترین خواندنِ ماهشان می‌شود، درست از آن رو که شتاب کم می‌شود و عجله از میان می‌رود.',
  'Translation audio': 'صدای ترجمه',
  'Translation volume': 'صدای ترجمه',
  'Translations': 'ترجمه‌ها',
  'Translations explain meaning and do not replace the Arabic Quran. Edition attribution remains visible in the reader.': 'ترجمه‌ها معنا را توضیح می‌دهند و جایگزین قرآن عربی نیستند. انتساب نسخه در حالت خواندن همچنان نمایان است.',
  'Transliteration': 'آوانویسی',
  'Travel': 'سفر',
  'Travelling': 'در سفر',
  'Trust and reliance': 'اعتماد و توکّل',
  'Truth or right': 'حق یا درستی',
  'Try Dubai, Makkah, London…': 'دوبی، مکه، لندن را امتحان کنید…',
  'Try again': 'تلاش دوباره',
  'Turkish': 'ترکی',
  'Turkish Lira': 'لیره ترکیه',
  'Turn on the women’s area': 'فعال کردن بخش بانوان',
  'Turn on this area': 'فعال کردن این بخش',
  'Two cycles needed': 'دو چرخه لازم است',
  'Two notifications sent — one quiet, one adhan.': 'دو اعلان فرستاده شد — یکی بی‌صدا، یکی اذان.',
  'Two or three interchangeable abayas — laundries wash same-day and cheaply': 'دو یا سه عبای قابل تعویض — لباس‌شویی‌ها همان‌روز و ارزان می‌شویند',
  'Two sets, not one — a wet set and a dry set': 'دو دست، نه یکی — یک دست خیس و یک دست خشک',
  'Two worships are lifted in these days — the prayer and the fast — and they are lifted as a mercy, not held back as a loss. Nearly everything else you do is untouched by them: the remembrance, the listening, the study, the asking. All of it is still yours, and all of it is already here.': 'در این روزها دو عبادت برداشته شده است — نماز و روزه — و این برداشتن از سرِ رحمت است، نه بازداشتن به عنوان زیان. تقریباً هر چه جز آن انجام می‌دهید از این دست‌نخورده می‌ماند: ذکر، شنیدن، درس گرفتن، دعا کردن. همهٔ آن‌ها هنوز از آنِ شماست و همهٔ آن‌ها همین‌جا حاضر است.',
  'Two worships are lifted in these days, and they are lifted as a mercy rather than taken as a loss. Nothing here is owed back, and nothing needs to be made up except the fasts. Where the scholars differ, the difference is described rather than settled — take it to someone you trust, and do not let it become a weight. This app records and explains; it does not rule.': 'در این روزها دو عبادت برداشته می‌شود، و این برداشتن از سرِ رحمت است نه از سرِ زیان. در اینجا چیزی پس‌دادنی نیست، و چیزی جز روزه‌ها نیاز به قضا ندارد. هر جا که علما اختلاف دارند، اختلاف توصیف می‌شود نه اینکه فیصله یابد — آن را نزدِ کسی ببرید که به او اعتماد دارید، و مگذارید باری بر دوشتان شود. این برنامه ثبت می‌کند و توضیح می‌دهد؛ حکم نمی‌دهد.',
