  'Verse-by-verse files, one track per ayah, with translation audio and reader controls.': 'فایل‌های آیه‌به‌آیه، یک ترک برای هر آیه، با صوت ترجمه و کنترل‌های خواندن.',
  'Verse-by-verse: one track for each ayah. Full-Surah: a complete recitation of the Surah.': 'آیه‌به‌آیه: برای هر آیه یک قطعه. کل سوره: تلاوت کامل سوره.',
  'Verses': 'آیات',
  'Verses affirming the absolute oneness, independence and incomparability of Allah.': 'آیاتی که یگانگیِ مطلق، بی‌نیازی و بی‌همتاییِ خدا را اثبات می‌کنند.',
  'Verses under this are drawn more often. Anything you flag yourself counts as weak whatever it scores.': 'آیات پایین‌تر از این بیشتر کشیده می‌شوند. هرچه را خودتان علامت بزنید، صرف‌نظر از نمره‌اش ضعیف شمرده می‌شود.',
