  'Waking up': 'بیدار شدن',
  'Walk from Safa to Marwah — that is one length — and back, seven lengths in all, finishing at Marwah. The Sa‘i is a rite of its own and is not shortened. Walk at your own pace; only the stretch between the two green markers is hurried.': 'از صفا به مروه بروید — این یک پیمایش است — و بازگردید، در مجموع هفت پیمایش، که در مروه پایان می‌یابد. سعی منسکی مستقل است و کوتاه نمی‌شود. به آهنگِ خود راه بروید؛ تنها فاصلهٔ میانِ دو نشانهٔ سبز با شتاب طی می‌شود.',
  'Wash away any impurity from the body.': 'هر نجاستی را از بدن بشویید.',
  'Wash both hands three times.': 'هر دو دست را سه بار بشویید.',
  'Wash both hands.': 'هر دو دست را بشویید.',
  'Wash the arms through the elbows, beginning with the right.': 'دست‌ها را تا آرنج بشویید، با آغاز از سمتِ راست.',
  'Wash the face.': 'صورت را بشویید.',
  'Wash the hands, then the private parts, then any impurity on the body.': 'دست‌ها را بشویید، سپس عورت را، سپس هر نجاستی را که بر بدن است.',
  'Wash your travel clothes in plain detergent, not the perfumed kind': 'لباس‌های سفرتان را با پودر ساده بشویید، نه از نوع معطر',
  'Watch full screen': 'تماشا در تمام‌صفحه',
