  'Welcome': 'خوش آمدید',
  'What Zakat is taken from': 'زکات از چه چیزی گرفته می‌شود',
  'What continues in these days, and the references': 'آنچه در این روزها ادامه می‌یابد، و منابع',
  'What counts as zakatable, how business stock is valued and which debts may be deducted differ between schools and situations. This figure is a careful estimate to take to a scholar, and your Zakat year matters as much as the total.': 'آنچه مشمول زکات است، کالای تجاری چگونه ارزش‌گذاری می‌شود و کدام بدهی‌ها را می‌توان کاست، میان مذاهب و موقعیت‌ها متفاوت است. این رقم برآوردی سنجیده است که باید نزد عالمی ببرید، و سالِ زکاتیِ شما به اندازهٔ کلِ مبلغ اهمیت دارد.',
  'What did you notice?': 'چه چیزی توجه شما را جلب کرد؟',
  'What ends the bleeding, the washing that follows it, and the days after childbirth. The well-known positions are described here; the ruling for your case belongs with a scholar you trust.': 'چه چیزی خون‌ریزی را پایان می‌دهد، غسلی که پس از آن می‌آید، و روزهای پس از زایمان. دیدگاه‌های شناخته‌شده اینجا بیان شده‌اند؛ حکمِ موردِ شما نزد عالمی است که به او اعتماد دارید.',
  'What falls due': 'آنچه سررسید می‌شود',
  'What is lifted, what continues, and what is owed afterwards. These are the well-known positions, described plainly — the ruling for your situation belongs with a scholar you trust.': 'چه برداشته شده، چه ادامه می‌یابد، و چه پس از آن بر عهده است. این‌ها دیدگاه‌های شناخته‌شده‌اند که به زبانی ساده بیان شده‌اند — حکمِ موردِ شما نزد عالمی است که به او اعتماد دارید.',
  'What is required': 'آنچه لازم است',
  'What is required of the washing, and how the Prophet ﷺ performed it.': 'آنچه در وضو واجب است، و اینکه پیامبر صلی‌الله علیه و آله و سلم چگونه آن را انجام می‌دادند.',
  'What is sent over the network': 'چه چیز از طریق شبکه فرستاده می‌شود',
