  'What you have flagged, and whatever scores lowest': 'آنچه نشانه گذاشته‌اید، و هرچه کمترین امتیاز را دارد',
  'What you open is stored on this device so it can be read again without a connection. Nothing you record is uploaded anywhere.': 'آنچه می‌گشایید روی این دستگاه ذخیره می‌شود تا بدون اتصال دوباره خوانده شود. هیچ‌یک از مواردی که ثبت می‌کنید به جایی بارگذاری نمی‌شود.',
  'What you owe, and what you have made up': 'آنچه بر عهده دارید، و آنچه قضا کرده‌اید',
  'What you own': 'آنچه دارید',
  'What you read': 'آنچه می‌خوانید',
  'What you say': 'آنچه می‌گویید',
  'What you work out, look up, keep track of, or watch — apart from the flow of the day.': 'آنچه محاسبه می‌کنید، جست‌وجو می‌کنید، پی می‌گیرید یا تماشا می‌کنید — جدای از جریانِ روز.',
  'When bleeding begins, start a cycle here and the count begins from that day.': 'هرگاه خون‌ریزی آغاز شد، چرخه‌ای را اینجا آغاز کنید و شمارش از همان روز شروع می‌شود.',
  'When bleeding runs past your pattern, this is the question it raises.': 'هرگاه خون‌ریزی از الگوی شما فراتر رود، این همان پرسشی است که پیش می‌آید.',
  'When do you sleep?': 'چه وقت می‌خوابید؟',
  'When the Surah ends': 'هنگامی که سوره پایان یابد',
  'When the app fetches something it sends only what that request needs — for example, the coordinates of the city you selected, in order to work out prayer times and the direction of the qibla. Those requests are not tied to you, and the app has no advertising identifier and runs no analytics.': 'وقتی برنامه چیزی می‌گیرد، تنها آنچه آن درخواست نیاز دارد می‌فرستد — برای نمونه، مختصات شهری که انتخاب کرده‌اید، تا اوقات نماز و جهت قبله محاسبه شود. این درخواست‌ها به شما پیوند نمی‌خورند، و برنامه شناسهٔ تبلیغاتی ندارد و تحلیل داده اجرا نمی‌کند.',
  'Where are your prayer times?': 'اوقات نماز شما کجاست؟',
  'Where it is': 'کجاست',
  'Where it is from': 'منشأ آن',
  'Where should prayer times be calculated?': 'اوقات نماز بر اساس کجا محاسبه شود؟',
  'Where the Quran text, prayer times, hadith and audio come from': 'منبع متن قرآن، اوقات نماز، حدیث و صدا',
  'Where the scholars differ': 'جایی که علما اختلاف دارند',
  'Where this came from': 'منشأ این',
  'Whether the app is felt as well as seen': 'اینکه برنامه افزون بر دیده شدن، حس هم شود',
  'Which colours the app wears. Each theme has its own light and dark.': 'برنامه کدام رنگ‌ها را بپوشد. هر پوسته نسخهٔ روشن و تیرهٔ خود را دارد.',
  'Which fasts your cycle may claim, and when they fall due': 'کدام روزه‌ها را چرخهٔ شما ممکن است بگیرد، و چه زمانی قضایشان فرا می‌رسد',
  'Which meaning beside the Arabic?': 'کدام معنا در کنار متن عربی؟',
  'Which one': 'کدام یک',
  'Which position this uses': 'این از کدام دیدگاه استفاده می‌کند',
  'Which voice with the recitation?': 'کدام صدا همراه تلاوت؟',
  'Who we ask': 'از چه کسی می‌پرسیم',
  'Who we ask about': 'دربارهٔ چه کسی می‌پرسیم',
  'Without end is the default: you stop when you know it, not when a counter runs out.': 'بی‌پایان، پیش‌فرض است: هر زمان که آن را بلد شدید بازمی‌ایستید، نه آن‌گاه که شمارنده به پایان برسد.',
  'Witr': 'وتر',
  'Witr, Duha and Tahajjud are voluntary, so they are kept apart from the five. Counting them together would flatter the obligation and turn these into a task.': 'وتر، چاشت و تهجد مستحب‌اند، از این رو از نمازهای پنج‌گانه جدا نگه داشته می‌شوند. شمردنِ آن‌ها در کنار هم، واجب را بزرگ‌تر از آنچه هست نشان می‌داد و این‌ها را به تکلیفی بدل می‌کرد.',
  'Witr, Duha and Tahajjud, kept apart from the five': 'وتر، چاشت و تهجّد، جدا از پنج نماز',
