  'Worked out from your attempts, never set by hand — so correcting one moves this immediately.': 'از تلاش‌های شما محاسبه می‌شود، هرگز دستی تنظیم نمی‌گردد — از این رو اصلاحِ یکی بلافاصله این را جابه‌جا می‌کند.',
