  'Your cycle varies somewhat, so treat the outer days as a question mark.': 'چرخهٔ شما تا حدی نوسان دارد، پس روزهای دورتر را محل تردید بدانید.',
  'Your cycle, purity and the fasts you owe': 'چرخهٔ شما، طهارت و روزه‌هایی که بر عهده دارید',
  'Your location never leaves this device. It is used to compute prayer times, Qibla and the fasting timetable, and you can clear it at any time.': 'مکان شما هرگز از این دستگاه بیرون نمی‌رود. برای محاسبهٔ اوقات نماز، قبله و جدول روزه به کار می‌رود، و هر زمان بخواهید می‌توانید آن را پاک کنید.',
  'Your mail app has the report. It is also saved in Settings.': 'گزارش در برنامهٔ رایانامهٔ شماست. در تنظیمات نیز ذخیره شده است.',
