  'Your own cycle lengths and averages, a prediction worked out from your history rather than an assumption, purity and ghusl guidance, the post-natal days, and a running scorecard of make-up fasts.': 'درازا و میانگینِ چرخهٔ خودتان، پیش‌بینی‌ای که از سابقهٔ شما محاسبه می‌شود نه از یک فرض، راهنماییِ طهارت و غسل، روزهای پس از زایمان، و کارنامه‌ای جاری از روزه‌های قضا.',
