  'Your prayer record, the surah and verse you last read, bookmarks, notes, reminder settings, the language you chose and the city you picked are stored on the device itself. Clearing the app’s storage or uninstalling removes them.': 'سابقهٔ نماز شما، سوره و آیه‌ای که آخرین بار خواندید، نشانک‌ها، یادداشت‌ها، تنظیمات یادآورها، زبانی که برگزیدید و شهری که انتخاب کردید، روی خودِ دستگاه ذخیره می‌شوند. پاک کردن حافظهٔ برنامه یا حذف آن، آن‌ها را از بین می‌برد.',
