  'Your worship, memorisation, notes, fasting and Qada are sealed with a password you choose. The password is never written down and cannot be recovered — not by this app, and not by anyone else.': 'عبادات، حفظ، یادداشت‌ها، روزه و قضای شما با رمزی که خود برمی‌گزینید بسته می‌شود. آن رمز هرگز نوشته نمی‌شود و قابل بازیابی نیست — نه از سوی این برنامه و نه از سوی هیچ کس دیگر.',
